/** Applies default values to zero-valued fields of Config. */
public static Gateway.Config.Builder configDefaults(Gateway.Config msg) {
if (msg == null) { return null; }
Gateway.Config.Builder builder = msg.toBuilder();
if (msg.getHealthPollIntervalSeconds() == 0) {
builder.setHealthPollIntervalSeconds(Helpers.DEFAULT_HEALTH_POLL_INTERVAL_SECONDS);
}
if (!msg.getEnableHttp()) {
builder.setEnableHttp(Helpers.DEFAULT_ENABLE_HTTP);
}
if (!msg.getEnableHttp3()) {
builder.setEnableHttp3(Helpers.DEFAULT_ENABLE_HTTP3);
}
if (!msg.getEnableGrpc()) {
builder.setEnableGrpc(Helpers.DEFAULT_ENABLE_GRPC);
}
if (!msg.hasTcpListener()) {
builder.setTcpListener(HostOuterClass.Host.newBuilder().setHost("0.0.0.0").setPort(8443).build());
}
if (!msg.hasQuicListener()) {
builder.setQuicListener(HostOuterClass.Host.newBuilder().setHost("0.0.0.0").setPort(8443).build());
}
return builder;
}
