// ============ TypeUndefaults ============
/** Resets Config fields that match defaults back to zero for minimal persistence. */
public static Gateway.Config.Builder configUndefaults(Gateway.Config msg) {
if (msg == null) { return null; }
Gateway.Config.Builder builder = msg.toBuilder();
if (msg.getHealthPollIntervalSeconds() == Helpers.DEFAULT_HEALTH_POLL_INTERVAL_SECONDS) {
builder.setHealthPollIntervalSeconds(0);
}
if (msg.getEnableHttp() == Helpers.DEFAULT_ENABLE_HTTP) {
builder.setEnableHttp(false);
}
if (msg.getEnableHttp3() == Helpers.DEFAULT_ENABLE_HTTP3) {
builder.setEnableHttp3(false);
}
if (msg.getEnableGrpc() == Helpers.DEFAULT_ENABLE_GRPC) {
builder.setEnableGrpc(false);
}
if (msg.hasTcpListener() && msg.getTcpListener().getHost().equals("0.0.0.0") && msg.getTcpListener().getPort() == 8443) {
builder.clearTcpListener();
}
if (msg.hasQuicListener() && msg.getQuicListener().getHost().equals("0.0.0.0") && msg.getQuicListener().getPort() == 8443) {
builder.clearQuicListener();
}
return builder;
}
