// ============ Merge ============
public static Gateway.Config.Builder mergeConfig(Gateway.Config dst, Gateway.Config src) {
Gateway.Config.Builder builder = dst.toBuilder();
if (dst.getHealthPollIntervalSeconds() == 0) { builder.setHealthPollIntervalSeconds(src.getHealthPollIntervalSeconds()); }
if (!dst.getEnableHttp()) { builder.setEnableHttp(src.getEnableHttp()); }
if (!dst.getEnableHttp3()) { builder.setEnableHttp3(src.getEnableHttp3()); }
if (!dst.getEnableGrpc()) { builder.setEnableGrpc(src.getEnableGrpc()); }
if (!dst.hasTcpListener() && src.hasTcpListener()) { builder.setTcpListener(src.getTcpListener()); }
if (!dst.hasQuicListener() && src.hasQuicListener()) { builder.setQuicListener(src.getQuicListener()); }
return builder;
}
public static Gateway.GatewayConfigState.Builder mergeGatewayConfigState(Gateway.GatewayConfigState dst, Gateway.GatewayConfigState src) {
Gateway.GatewayConfigState.Builder builder = dst.toBuilder();
if (!dst.hasConfig() && src.hasConfig()) { builder.setConfig(src.getConfig()); }
else if (dst.hasConfig() && src.hasConfig()) { builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build()); }
return builder;
}
